import React, { useState, useEffect, useCallback } from 'react';
import { supabase } from '../../supabaseClient';

const ArtistPricingSettings = ({ userId }) => {
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [pricing, setPricing] = useState({
    base_rate: '',
    rate_type: 'per_render',
    average_delivery_time: '',
    specialties: [],
    price_per_room_min: '',
    price_per_room_max: '',
    renders_included_per_room: 3
  });
  const [message, setMessage] = useState('');

  const specialtyOptions = [
    'Residential',
    'Commercial',
    'Interior Design',
    'Exterior',
    'Landscaping',
    'Industrial',
    'Urban Planning',
    'Product Visualization'
  ];

  useEffect(() => {
    loadPricing();
  }, [userId, loadPricing]);

  const loadPricing = useCallback(async () => {
    try {
      const { data, error } = await supabase
        .from('profiles')
        .select('base_rate, rate_type, average_delivery_time, specialties, price_per_room_min, price_per_room_max, renders_included_per_room')
        .eq('id', userId)
        .single();

      if (error) throw error;

      if (data) {
        setPricing({
          base_rate: data.base_rate || '',
          rate_type: data.rate_type || 'per_render',
          average_delivery_time: data.average_delivery_time || '',
          specialties: data.specialties || [],
          price_per_room_min: data.price_per_room_min || '',
          price_per_room_max: data.price_per_room_max || '',
          renders_included_per_room: data.renders_included_per_room || 3
        });
      }
    } catch (error) {
      console.error('Error loading pricing:', error);
    } finally {
      setLoading(false);
    }
  }, [userId]);

  const handleSave = async (e) => {
    e.preventDefault();
    setSaving(true);
    setMessage('');

    try {
      const { error } = await supabase
        .from('profiles')
        .update({
          base_rate: pricing.base_rate || null,
          rate_type: pricing.rate_type,
          average_delivery_time: pricing.average_delivery_time || null,
          specialties: pricing.specialties,
          price_per_room_min: pricing.price_per_room_min || null,
          price_per_room_max: pricing.price_per_room_max || null,
          renders_included_per_room: pricing.renders_included_per_room
        })
        .eq('id', userId);

      if (error) throw error;

      setMessage('Pricing settings saved successfully!');
      setTimeout(() => setMessage(''), 3000);
    } catch (error) {
      console.error('Error saving pricing:', error);
      setMessage('Error saving settings. Please try again.');
    } finally {
      setSaving(false);
    }
  };

  const toggleSpecialty = (specialty) => {
    setPricing(prev => ({
      ...prev,
      specialties: prev.specialties.includes(specialty)
        ? prev.specialties.filter(s => s !== specialty)
        : [...prev.specialties, specialty]
    }));
  };

  if (loading) {
    return <div className="loading">Loading...</div>;
  }

  return (
    <div className="pricing-settings">
      <h2>Pricing Settings</h2>
      <p className="subtitle">Configure your base rate and specialties</p>

      {message && (
        <div className={`message ${message.includes('Error') ? 'error' : 'success'}`}>
          {message}
        </div>
      )}

      <form onSubmit={handleSave}>
        {/* Base Rate */}
        <div className="form-group">
          <label>Base Rate *</label>
          <div className="input-with-prefix">
            <span className="prefix">R$</span>
            <input
              type="number"
              step="0.01"
              min="0"
              value={pricing.base_rate}
              onChange={(e) => setPricing({ ...pricing, base_rate: e.target.value })}
              placeholder="Ex: 800.00"
              required
            />
          </div>
        </div>

        {/* Rate Type */}
        <div className="form-group">
          <label>Billing Type *</label>
          <select
            value={pricing.rate_type}
            onChange={(e) => setPricing({ ...pricing, rate_type: e.target.value })}
            required
          >
            <option value="per_render">Per Render</option>
            <option value="per_hour">Per Hour</option>
            <option value="per_project">Per Project</option>
          </select>
        </div>

        {/* Average Delivery Time */}
        <div className="form-group">
          <label>Average Delivery Time (days)</label>
          <input
            type="number"
            min="1"
            value={pricing.average_delivery_time}
            onChange={(e) => setPricing({ ...pricing, average_delivery_time: e.target.value })}
            placeholder="Ex: 7"
          />
          <small>How long does it typically take to complete a project?</small>
        </div>

        {/* Price Per Room Section */}
        <div className="form-group" style={{
          background: '#f8f9fa',
          padding: '20px',
          borderRadius: '8px',
          border: '1px solid #e9ecef'
        }}>
          <label style={{
            fontSize: '16px',
            fontWeight: '600',
            marginBottom: '15px',
            display: 'block'
          }}>
            💰 Price Per Room (Optional)
          </label>
          <small style={{ display: 'block', marginBottom: '15px', color: '#666' }}>
            Set a price range per room including {pricing.renders_included_per_room} renders
          </small>

          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '15px' }}>
            <div>
              <label style={{ fontSize: '14px', marginBottom: '5px', display: 'block' }}>
                Minimum Price
              </label>
              <div className="input-with-prefix">
                <span className="prefix">R$</span>
                <input
                  type="number"
                  step="0.01"
                  min="0"
                  value={pricing.price_per_room_min}
                  onChange={(e) => setPricing({ ...pricing, price_per_room_min: e.target.value })}
                  placeholder="Ex: 500"
                />
              </div>
            </div>

            <div>
              <label style={{ fontSize: '14px', marginBottom: '5px', display: 'block' }}>
                Maximum Price
              </label>
              <div className="input-with-prefix">
                <span className="prefix">R$</span>
                <input
                  type="number"
                  step="0.01"
                  min="0"
                  value={pricing.price_per_room_max}
                  onChange={(e) => setPricing({ ...pricing, price_per_room_max: e.target.value })}
                  placeholder="Ex: 1000"
                />
              </div>
            </div>

            <div>
              <label style={{ fontSize: '14px', marginBottom: '5px', display: 'block' }}>
                Renders Included
              </label>
              <select
                value={pricing.renders_included_per_room}
                onChange={(e) => setPricing({ ...pricing, renders_included_per_room: parseInt(e.target.value) })}
                style={{
                  width: '100%',
                  padding: '10px',
                  border: '1px solid #ddd',
                  borderRadius: '6px',
                  background: 'white'
                }}
              >
                <option value={1}>1 render</option>
                <option value={2}>2 renders</option>
                <option value={3}>3 renders (recommended)</option>
                <option value={4}>4 renders</option>
                <option value={5}>5 renders</option>
              </select>
            </div>
          </div>

          {pricing.price_per_room_min && pricing.price_per_room_max && (
            <div style={{
              marginTop: '15px',
              padding: '12px',
              background: '#e7f3ff',
              borderRadius: '6px',
              border: '1px solid #b3d9ff'
            }}>
              <strong>Example:</strong> A project with 5 rooms would cost between{' '}
              <strong>R$ {(parseFloat(pricing.price_per_room_min) * 5).toFixed(2)}</strong> and{' '}
              <strong>R$ {(parseFloat(pricing.price_per_room_max) * 5).toFixed(2)}</strong>
              <br />
              <small style={{ color: '#0066cc' }}>
                ({pricing.renders_included_per_room} renders × 5 rooms = {pricing.renders_included_per_room * 5} total renders)
              </small>
            </div>
          )}
        </div>

        {/* Specialties */}
        <div className="form-group">
          <label>Specialties</label>
          <div className="specialty-grid">
            {specialtyOptions.map(specialty => (
              <button
                key={specialty}
                type="button"
                className={`specialty-tag ${pricing.specialties.includes(specialty) ? 'active' : ''}`}
                onClick={() => toggleSpecialty(specialty)}
              >
                {specialty}
              </button>
            ))}
          </div>
        </div>

        <button type="submit" className="btn-primary" disabled={saving}>
          {saving ? 'Saving...' : 'Save Settings'}
        </button>
      </form>

      <style jsx>{`
        .pricing-settings {
          max-width: 600px;
        }

        .subtitle {
          color: #666;
          margin-bottom: 30px;
        }

        .message {
          padding: 12px;
          border-radius: 6px;
          margin-bottom: 20px;
        }

        .message.success {
          background: #d4edda;
          color: #155724;
          border: 1px solid #c3e6cb;
        }

        .message.error {
          background: #f8d7da;
          color: #721c24;
          border: 1px solid #f5c6cb;
        }

        .form-group {
          margin-bottom: 24px;
        }

        .form-group label {
          display: block;
          font-weight: 600;
          margin-bottom: 8px;
          color: #333;
        }

        .form-group small {
          display: block;
          color: #666;
          font-size: 13px;
          margin-top: 6px;
        }

        .input-with-prefix {
          display: flex;
          align-items: center;
          border: 1px solid #ddd;
          border-radius: 6px;
          overflow: hidden;
        }

        .prefix {
          padding: 10px 12px;
          background: #f5f5f5;
          border-right: 1px solid #ddd;
          font-weight: 600;
          color: #666;
        }

        .input-with-prefix input {
          border: none;
          flex: 1;
          padding: 10px 12px;
        }

        .specialty-grid {
          display: grid;
          grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
          gap: 10px;
          margin-top: 10px;
        }

        .specialty-tag {
          padding: 10px 16px;
          border: 2px solid #ddd;
          border-radius: 6px;
          background: white;
          cursor: pointer;
          transition: all 0.2s;
          font-size: 14px;
        }

        .specialty-tag:hover {
          border-color: #6C63FF;
          background: #f8f8ff;
        }

        .specialty-tag.active {
          border-color: #6C63FF;
          background: #6C63FF;
          color: white;
        }

        .btn-primary {
          width: 100%;
          padding: 12px;
          background: #6C63FF;
          color: white;
          border: none;
          border-radius: 6px;
          font-size: 16px;
          font-weight: 600;
          cursor: pointer;
          transition: background 0.2s;
        }

        .btn-primary:hover:not(:disabled) {
          background: #5a52d5;
        }

        .btn-primary:disabled {
          opacity: 0.6;
          cursor: not-allowed;
        }
      `}</style>
    </div>
  );
};

export default ArtistPricingSettings;